arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *sername*) echo "x-access-token" ;;
  *) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh
GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINALPROMPT=0 git -C /tmp/conv-rachel push https://x-access-token@github.com/igor-makarov/beetle-in-the-anthill.git HEAD:refs/heads/friend/rachel 2>&1 | tail -5
